// HL-PROFIT1 Word report renderer. Reads ONLY research/model/logs/s1/s1_profit1_docx_data.json
// (itself generated by research/model/s1_profit1_docx_data.py, which reads only the committed
// engine/generator/taskb JSON files) and formats it into Word XML. This script contains NO numbers
// of its own -- every figure that appears in the output came from the data JSON. Every heading/intro
// sentence that needs a CONFIG value or a count is pre-built in docx_data.json's "strings" block, not
// typed here (checker's requirement, 2026-11-09).
//
//   cd research/model && npm install && node s1_profit1_docx_render.js
//
const fs = require("fs");
const path = require("path");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType,
  ShadingType, HeadingLevel, AlignmentType, ImageRun, PageBreak, BorderStyle,
} = require("docx");

const ROOT = path.resolve(__dirname, "..", "..");
const DATA_PATH = path.join(ROOT, "research/model/logs/s1/s1_profit1_docx_data.json");
const OUT_PATH = path.join(process.env.HOME, "Downloads/HL-PROFIT1_backtest_24_runs.docx");

const data = JSON.parse(fs.readFileSync(DATA_PATH, "utf8"));

const PAGE_W = 12240; // US letter DXA
const MARGIN = 720;
const TABLE_W = PAGE_W - 2 * MARGIN;

function pct(x, d = 2) { return x === null || x === undefined || Number.isNaN(x) ? "n/a" : (x * 100).toFixed(d) + "%"; }
function num(x, d = 2) { return x === null || x === undefined || Number.isNaN(x) ? "n/a" : Number(x).toFixed(d); }
function money(x, d = 2) { return x === null || x === undefined || Number.isNaN(x) ? "n/a" : "$" + Number(x).toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d }); }
function int(x) { return x === null || x === undefined ? "n/a" : Number(x).toLocaleString("en-US"); }

function h1(text) { return new Paragraph({ text, heading: HeadingLevel.HEADING_1 }); }
function h2(text) { return new Paragraph({ text, heading: HeadingLevel.HEADING_2 }); }
function h3(text) { return new Paragraph({ text, heading: HeadingLevel.HEADING_3 }); }
function p(text) { return new Paragraph({ children: [new TextRun(text)] }); }
function bullets(items) {
  return items.map((t) => new Paragraph({ text: t, bullet: { level: 0 } }));
}

function cell(text, opts = {}) {
  return new TableCell({
    width: { size: opts.width || 1000, type: WidthType.DXA },
    shading: opts.header ? { type: ShadingType.CLEAR, fill: "D9D9D9" } : undefined,
    children: [new Paragraph({ children: [new TextRun({ text: String(text), bold: !!opts.header })] })],
  });
}

function table(headers, rows, widths) {
  const w = widths || headers.map(() => Math.floor(TABLE_W / headers.length));
  const headerRow = new TableRow({ children: headers.map((hh, i) => cell(hh, { header: true, width: w[i] })) });
  const bodyRows = rows.map((r) => new TableRow({ children: r.map((v, i) => cell(v, { width: w[i] })) }));
  return new Table({ width: { size: TABLE_W, type: WidthType.DXA }, columnWidths: w, rows: [headerRow, ...bodyRows] });
}

function kvTable(obj, keyWidth = 3500) {
  const rows = Object.entries(obj).map(([k, v]) => [k, typeof v === "object" ? JSON.stringify(v) : String(v)]);
  return table(["field", "value"], rows, [keyWidth, TABLE_W - keyWidth]);
}

const sections = [];

// ---------------------------------------------------------------------------
// 1. Summary
// ---------------------------------------------------------------------------
const body = [];
const S = data.strings;
body.push(new Paragraph({ text: "HL-PROFIT1: Portfolio Backtest of S1's Live Picks on Hyperliquid", heading: HeadingLevel.TITLE }));
body.push(p(S.intro));
body.push(h1("1. Summary"));

body.push(h2("Configuration"));
body.push(kvTable(data.summary.config));

body.push(h2(S.test_period_heading));
body.push(table(["fold", "start", "end"], data.summary.test_blocks.map((b) => [b.fold, b.start, b.end])));

body.push(h2(S.all24_heading));
body.push(table(
  ["q", "stop", "fee", "final_equity", "total_return", "n_trades", "win_rate", "profit_factor", "sharpe", "sortino", "max_dd_pct"],
  data.summary.all24_table.map((r) => [
    r.q, r.stop, r.fee, money(r.final_equity), pct(r.total_return), int(r.n_trades),
    pct(r.win_rate), num(r.profit_factor, 3), num(r.sharpe, 2), num(r.sortino, 2), pct(r.max_dd_pct),
  ]),
  [700, 700, 700, 1300, 1200, 1100, 1100, 1300, 900, 900, 1100],
));
body.push(p(S.runs_above_start));

body.push(h2("Key findings"));
body.push(...bullets(data.summary.key_findings));

body.push(h2("Known gaps"));
body.push(...bullets(data.summary.known_gaps));

body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------------------
// 2. Glossary
// ---------------------------------------------------------------------------
body.push(h1("2. Glossary"));
const glossary = [
  ["q", "pick threshold -- the fraction of events taken as a trade (1% is the loosest, 0.1% the tightest)."],
  ["stop", "a stop-loss in standard deviations (sigma) of the pair spread; 'none' means no stop, hold to timeout."],
  ["z", "the spread's distance from its mean at entry, in sigma units -- the signal S1 scores."],
  ["p_cal_10h", "S1-H's calibrated probability the spread reverts to mean within 10 hours."],
  ["final_equity", "account value in USD at the end of the 7-month test period, starting from $1,000."],
  ["total_return", "final_equity / 1000 - 1."],
  ["max_open", "the maximum number of concurrent open positions allowed."],
  ["margin skip", "a pick that was not taken because taking it would exceed the account's margin."],
  ["profit_factor", "sum of winning trades' net $ divided by the absolute sum of losing trades' net $."],
  ["distance to liquidation (ratio)", "account_value / maintenance margin; 1.0 would mean liquidation."],
  ["in-sample", "a result where the rule or threshold was chosen after seeing these same test months -- not yet validated out of sample."],
];
body.push(table(["term", "meaning"], glossary, [2000, TABLE_W - 2000]));
body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------------------
// 3. Comparisons by stop / fee / q (re-slices of the same all-24 table)
// ---------------------------------------------------------------------------
body.push(h1(S.comparisons_heading));
for (const q of [0.01, 0.005, 0.001]) {
  body.push(h2(`q = ${q}`));
  const rows = data.summary.all24_table.filter((r) => r.q === q);
  body.push(table(
    ["stop", "fee", "final_equity", "total_return", "win_rate", "profit_factor", "sharpe"],
    rows.map((r) => [r.stop, r.fee, money(r.final_equity), pct(r.total_return), pct(r.win_rate), num(r.profit_factor, 3), num(r.sharpe, 2)]),
  ));
}
body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------------------
// 4. Per-run detail (24 base runs)
// ---------------------------------------------------------------------------
body.push(h1(S.per_run_heading));
const imgCache = {};
for (const r of data.per_run_sections) {
  body.push(h2(`${r.key}  (q=${r.q}, stop=${r.stop}, fee=${r.fee})`));

  body.push(h3("Results"));
  body.push(kvTable({
    final_equity: money(r.results.final_equity),
    total_return: pct(r.results.total_return),
    cagr: `${pct(r.results.cagr)} (n_days=${r.results.cagr_n_days})`,
    n_trades: int(r.results.n_trades),
    win_rate: pct(r.results.win_rate),
    stop_share: pct(r.results.stop_share),
    timeout_share: pct(r.results.timeout_share),
    profit_factor: num(r.results.profit_factor, 3),
    sharpe: `${num(r.results.sharpe, 2)} (sortino ${num(r.results.sortino, 2)}, n_days=${r.results.sharpe_sortino_n_days})`,
    mean_net: num(r.results.mean_net, 4) + " / median " + num(r.results.median_net, 4),
    mean_win_loss: num(r.results.mean_win, 4) + " / " + num(r.results.mean_loss, 4),
    mean_holding_minutes: num(r.results.mean_holding_minutes, 1),
  }));

  body.push(h3("Drawdown and distance to liquidation"));
  body.push(kvTable({
    max_dd_usd: money(r.drawdown.max_dd_usd), max_dd_pct: pct(r.drawdown.max_dd_pct),
    dd_start: r.drawdown.start, dd_bottom: r.drawdown.bottom, dd_recovery: r.drawdown.recovery || "not recovered",
    longest_underwater_days: r.drawdown.longest_underwater_days,
    min_distance_ratio: num(r.distance_to_liquidation.min, 3),
    median_distance_ratio: num(r.distance_to_liquidation.median, 3),
    date_of_min: r.distance_to_liquidation.date_of_min,
  }));

  body.push(h3("Costs"));
  body.push(kvTable({
    total_gross: money(r.costs.total_gross),
    fee: `${money(r.costs.total_fee)} (${pct(r.costs.fee_share_of_gross)} of gross)`,
    slippage: `${money(r.costs.total_slippage)} (${pct(r.costs.slippage_share_of_gross)} of gross)`,
    funding_paid: `${money(r.costs.total_funding_paid)} (${pct(r.costs.funding_paid_share_of_gross)} of gross)`,
    funding_received: `${money(r.costs.total_funding_received)} (${pct(r.costs.funding_received_share_of_gross)} of gross)`,
  }));

  body.push(h3("Skips and liquidations"));
  body.push(kvTable({ ...r.skips, n_liquidations: r.n_liquidations }));

  body.push(h3("Leverage and risk"));
  body.push(kvTable({
    peak_margin_used: money(r.leverage_risk.peak_margin_used),
    mean_open_positions: num(r.leverage_risk.mean_open_positions, 2),
    max_open_positions: r.leverage_risk.max_open_positions,
  }));

  body.push(h3(`Monthly P&L (n_months_positive=${r.n_months_positive}/${data.summary.n_folds})`));
  const foldKeys = Object.keys(r.monthly).filter((k) => k !== "outside").sort((a, b) => Number(a) - Number(b));
  const monthRows = foldKeys.map((k) => {
    const m = r.monthly[k];
    return [k, m.n_days, m.total_pnl_usd === null ? "n/a" : money(m.total_pnl_usd), m.total_pnl_pct === null ? "n/a" : pct(m.total_pnl_pct)];
  });
  const out = r.monthly["outside"];
  monthRows.push(["outside", out.n_days, money(out.total_pnl_usd), "n/a"]);
  body.push(table(["fold", "n_days", "total_pnl_usd", "total_pnl_pct"], monthRows));

  if (Object.keys(r.top5_coins).length) {
    body.push(h3("Top / bottom 5 coins (net $, each trade counted for both coins)"));
    body.push(table(["top coin", "net"], Object.entries(r.top5_coins).map(([c, v]) => [c, money(v)])));
    body.push(table(["bottom coin", "net"], Object.entries(r.bottom5_coins).map(([c, v]) => [c, money(v)])));
  }
  if (Object.keys(r.top5_pairs).length) {
    body.push(h3("Top / bottom 5 pairs (net $)"));
    body.push(table(["top pair", "net"], Object.entries(r.top5_pairs).map(([c, v]) => [c, money(v)])));
    body.push(table(["bottom pair", "net"], Object.entries(r.bottom5_pairs).map(([c, v]) => [c, money(v)])));
  }

  if (r.equity_png) {
    const imgPath = path.join(ROOT, r.equity_png);
    if (fs.existsSync(imgPath)) {
      if (!imgCache[imgPath]) imgCache[imgPath] = fs.readFileSync(imgPath);
      body.push(h3("Equity curve (all 4 stops for this q/fee, shared PNG)"));
      body.push(new Paragraph({ children: [new ImageRun({ type: "png", data: imgCache[imgPath], transformation: { width: 500, height: 312 } })] }));
    }
  }
  body.push(new Paragraph({ children: [new PageBreak()] }));
}

// ---------------------------------------------------------------------------
// 5. EV check (base, stop=none only)
// ---------------------------------------------------------------------------
body.push(h1("5. EV check (base, stop=none only; fold 1 not scored)"));
body.push(p("EV here is descriptive only -- it does not reliably rank realised net in this data, and no claim that it predicts profit should be drawn from these tables."));
for (const [key, ev] of Object.entries(data.ev_check)) {
  if (!ev) continue;
  body.push(h2(`${key} (n_scored=${int(ev.n_scored)})`));
  const qkeys = Object.keys(ev.quintiles).sort((a, b) => Number(a) - Number(b));
  body.push(table(
    ["quintile", "n", "mean_ev", "mean_realised_net"],
    qkeys.map((qq) => [qq, int(ev.quintiles[qq].n), num(ev.quintiles[qq].mean_ev, 4), num(ev.quintiles[qq].mean_realised_net, 4)]),
  ));
}
body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------------------
// 6. Variant comparison: base / open20 / z3_open10 / z3_open20
// ---------------------------------------------------------------------------
body.push(h1("6. Comparison: base vs open20 vs z3_open10 vs z3_open20"));
body.push(p(S.variant_intro));
const vc = data.variant_comparison;
const groups = {};
for (const r of vc) {
  const gk = `q${r.q}_stop${r.stop}_fee${r.fee}`;
  (groups[gk] = groups[gk] || []).push(r);
}
for (const [gk, rows] of Object.entries(groups)) {
  body.push(h3(gk));
  body.push(table(
    ["variant", "final_equity", "total_return", "n_trades", "win_rate", "profit_factor", "sharpe", "max_dd_pct", "min_dist_ratio", "skips", "liq"],
    rows.map((r) => [r.variant, money(r.final_equity), pct(r.total_return), int(r.n_trades), pct(r.win_rate), num(r.profit_factor, 3), num(r.sharpe, 2), pct(r.max_dd_pct), num(r.min_dist_ratio, 3), int(r.skip_total), r.n_liquidations]),
    [1900, 1000, 900, 800, 800, 900, 700, 900, 900, 700, 500],
  ));
}
body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------------------
// 7. Task B: |z| x p_cal descriptive grid
// ---------------------------------------------------------------------------
body.push(h1(S.taskb_heading));
body.push(p("Descriptive only -- no filter or rule is chosen here. Any threshold read off these tables needs the vault or paper-trading check before it means anything."));
body.push(h2(S.taskb_mono_heading));
body.push(table(
  ["measure", "direction", "monotone q0->q4", "top quintile highest"],
  Object.entries(data.taskb.monotonicity_checks).map(([name, c]) => [
    name, c.direction, `${c.n_monotone}/${c.n_runs}`,
    c.n_top_quintile_highest === null ? "n/a" : `${c.n_top_quintile_highest}/${c.n_runs}`,
  ]),
));
for (const [key, r] of Object.entries(data.taskb.runs)) {
  body.push(h3(`${key} (n_trades=${int(r.n_trades)})`));
  body.push(p("|z| quintiles:"));
  body.push(table(
    ["q", "range", "n", "win_rate", "mean_return", "median_return", "profit_factor"],
    r.abs_z_quintiles.map((row) => [row.quintile, `[${num(row.bin_lo, 3)}, ${num(row.bin_hi, 3)}]`, int(row.n), pct(row.win_rate), num(row.mean_return, 4), num(row.median_return, 4), num(row.profit_factor, 3)]),
  ));
  body.push(p("p_cal_10h quintiles:"));
  body.push(table(
    ["q", "range", "n", "win_rate", "mean_return", "median_return", "profit_factor"],
    r.p_cal_quintiles.map((row) => [row.quintile, `[${num(row.bin_lo, 4)}, ${num(row.bin_hi, 4)}]`, int(row.n), pct(row.win_rate), num(row.mean_return, 4), num(row.median_return, 4), num(row.profit_factor, 3)]),
  ));
}
body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------------------
// 8. Method and data
// ---------------------------------------------------------------------------
body.push(h1("8. Method and data"));
body.push(h2("Price data"));
const pv = data.method_data.price_verification;
body.push(p(`Prices come from Hyperliquid build2's d3/asm 1-minute trade-price bars, not asset_ctxs mid-price. This was confirmed by an exact sha256 match on ${pv.sha256_match}/${pv.sha256_total} locally-held files and an exact match on ${int(pv.derived_value_exact_matches)}/${int(pv.derived_value_exact_matches + pv.derived_value_mismatches)} derived 30-minute values against the archive.`));
body.push(h2("Cross-check against v1's own labels"));
for (const [label, cc] of Object.entries(data.method_data.cross_check_by_variant)) {
  body.push(p(`${label}: ${cc.mismatched_total} mismatched out of ${int(cc.events_total)} ${cc.label}.`));
}
body.push(h2("p_cal (calibrated probability)"));
body.push(p("p_cal_10h is S1-H's isotonic correction, refit here by calling the same function S1-H used, and the pooled top-1% mean p_cal is asserted against S1-H's own reported value."));
body.push(h2("Costs model"));
body.push(p(`slippage_spread_share = ${data.method_data.slippage_spread_share} for this reported run (slippage excluded by the user's choice -- the legs are small). Fees and funding are applied as described in the per-run cost tables above.`));
if (data.method_data.pooled_cost_share_diagnostic) {
  const d = data.method_data.pooled_cost_share_diagnostic;
  body.push(p(`${d.label}: n_trades=${int(d.n_trades)}, gross=${money(d.gross)}, fee=${money(d.fee)}, funding_net=${money(d.funding_net)}, net=${money(d.net)}, fee_share_of_gross=${pct(d.fee_share_of_gross)}.`));
}
body.push(h2("Account rules"));
body.push(bullets([
  S.account_rules_start,
  "1:|beta| leg split per pair; cross-margin liquidation via account_value/maintenance ratio.",
  "Admission ordering: existing positions processed before new admissions; ties broken by p_cal with a seeded tie-break.",
  "A liquidating minute admits nothing new.",
  "Taker-rate forced liquidation; funding applied hourly from realized funding history.",
]));

const doc = new Document({
  styles: {
    default: {
      heading1: { run: { font: "Arial", size: 32, bold: true }, paragraph: { spacing: { before: 240, after: 120 }, keepNext: true } },
      heading2: { run: { font: "Arial", size: 26, bold: true }, paragraph: { spacing: { before: 200, after: 100 }, keepNext: true } },
      heading3: { run: { font: "Arial", size: 22, bold: true }, paragraph: { spacing: { before: 160, after: 80 }, keepNext: true } },
      title: { run: { font: "Arial", size: 40, bold: true }, paragraph: { spacing: { before: 0, after: 200 } } },
    },
  },
  sections: [{
    properties: { page: { size: { width: PAGE_W, height: 15840 }, margin: { top: MARGIN, bottom: MARGIN, left: MARGIN, right: MARGIN } } },
    children: body,
  }],
});

Packer.toBuffer(doc).then((buf) => {
  fs.writeFileSync(OUT_PATH, buf);
  console.log(`[DOCX] wrote ${OUT_PATH} (${buf.length} bytes)`);
});
